class PreloadedSupermarket {
  final String name;
  final double latitude;
  final double longitude;
  final double radiusMeters;
  final String city;
  final String? address;
  final String icon;
  final String colorHex;

  const PreloadedSupermarket({
    required this.name,
    required this.latitude,
    required this.longitude,
    this.radiusMeters = 200.0,
    required this.city,
    this.address,
    this.icon = 'store',
    this.colorHex = '#1E88E5',
  });
}

class DefaultSupermarketsData {
  static final RegExp _tokenSplitRegex = RegExp(r'[\s\-_/]+');

  static String normalize(String text) => _normalize(text);

  static String _normalize(String text) {
    var result = text.toLowerCase().trim();
    const withDia = 'àáâãäåòóôõöøèéêëçìíîïùúûüñ';
    const noDia   = 'aaaaaaooooooeeeeciiiiuuuun';
    for (int i = 0; i < withDia.length; i++) {
      result = result.replaceAll(withDia[i], noDia[i]);
    }
    return result;
  }

  /// Lista oficial de redes principais para filtros rápidos
  static const List<String> mainChains = [
    'Todas',
    'Guanabara',
    'Supermarket',
    'Rede Economia',
    'Assaí',
    'Mundial',
    'Real',
    'Atacadão',
    'Grand Marché',
    'Prezunic',
    'Princesa',
    'Super Rede',
    'Dom Atacadista',
    'Pão de Açúcar',
    'Zona Sul',
    'Multi Market',
    'Carrefour',
    'Extra',
    'Dia',
    'Hortifruti',
    'Extrabom',
    'Outras',
  ];

  /// Identifica a rede (bandeira) de um supermercado pelo nome
  static String getChainName(String marketName) {
    final norm = _normalize(marketName);
    if (norm.contains('guanabara')) return 'Guanabara';
    if (norm.contains('grand marche')) return 'Grand Marché';
    if (norm.contains('supermarket')) return 'Supermarket';
    if (norm.contains('rede economia')) return 'Rede Economia';
    if (norm.contains('assai')) return 'Assaí';
    if (norm.contains('mundial')) return 'Mundial';
    if (norm.contains('real supermercado') || norm.startsWith('real -') || norm.startsWith('real ')) return 'Real';
    if (norm.contains('atacadao')) return 'Atacadão';
    if (norm.contains('prezunic')) return 'Prezunic';
    if (norm.contains('princesa')) return 'Princesa';
    if (norm.contains('super rede')) return 'Super Rede';
    if (norm.contains('dom atacadista')) return 'Dom Atacadista';
    if (norm.contains('pao de acucar')) return 'Pão de Açúcar';
    if (norm.contains('zona sul')) return 'Zona Sul';
    if (norm.contains('multi market') || norm.contains('multimarket')) return 'Multi Market';
    if (norm.contains('carrefour')) return 'Carrefour';
    if (norm.contains('extrabom')) return 'Extrabom';
    if (norm.contains('mercado extra') || norm.startsWith('extra ') || norm.startsWith('extra -') || norm == 'extra') return 'Extra';
    if (norm.contains('supermercado dia') || norm.startsWith('dia ') || norm.startsWith('dia -')) return 'Dia';
    if (norm.contains('hortifruti') || norm.contains('natural da terra')) return 'Hortifruti';
    return 'Outras';
  }

  /// Verifica se o supermercado pertence à rede filtrada
  static bool matchesChain(String marketName, String selectedChain) {
    if (selectedChain.isEmpty || selectedChain == 'Todas' || selectedChain == 'Todos') {
      return true;
    }
    return getChainName(marketName).toLowerCase() == selectedChain.toLowerCase();
  }

  /// Verifica se o supermercado corresponde ao texto pesquisado (nome, rede, endereço ou cidade)
  static bool matchesSearch(String marketName, String rawQuery, {PreloadedSupermarket? preloaded}) {
    final qNorm = _normalize(rawQuery);
    if (qNorm.isEmpty) return true;

    final pre = preloaded ?? findMatch(marketName);
    final nameNorm = _normalize(marketName);
    final addrNorm = pre?.address != null ? _normalize(pre!.address!) : '';
    final cityNorm = pre != null ? _normalize(pre.city) : '';
    final chainNorm = _normalize(getChainName(marketName));

    final combined = '$nameNorm $chainNorm $addrNorm $cityNorm';
    if (combined.contains(qNorm)) return true;

    final tokens = qNorm.split(_tokenSplitRegex).where((t) => t.isNotEmpty);
    return tokens.every((t) => combined.contains(t));
  }

  static Map<String, PreloadedSupermarket>? _exactByNormName;
  static List<MapEntry<String, PreloadedSupermarket>>? _normalizedEntries;
  static final Map<String, PreloadedSupermarket?> _simpleMatchCache = {};

  static void _ensureIndexes() {
    if (_exactByNormName != null && _normalizedEntries != null) return;
    final exact = <String, PreloadedSupermarket>{};
    final entries = <MapEntry<String, PreloadedSupermarket>>[];
    for (final s in all) {
      final n = _normalize(s.name);
      exact[n] = s;
      entries.add(MapEntry(n, s));
    }
    // Alias canônico para Guanabara Niterói
    if (exact.containsKey('supermercados guanabara - niteroi')) {
      exact['supermercados guanabara'] = exact['supermercados guanabara - niteroi']!;
    }
    _exactByNormName = exact;
    _normalizedEntries = entries;
  }

  /// Encontra o supermercado do catálogo mais próximo dentro do seu raio de detecção (offline O(N) com bounding-box)
  static PreloadedSupermarket? findNearestWithinRadius(double lat, double lng) {
    PreloadedSupermarket? closest;
    double minDegSq = double.infinity;
    for (final s in all) {
      final dLat = (s.latitude - lat).abs();
      final dLng = (s.longitude - lng).abs();
      // ~350m max radius in degrees (~0.0035 deg)
      if (dLat > 0.0035 || dLng > 0.0035) continue;
      final approxMeters = ((dLat * 111320.0) * (dLat * 111320.0)) +
          ((dLng * 102000.0) * (dLng * 102000.0));
      final maxSq = s.radiusMeters * s.radiusMeters;
      if (approxMeters <= maxSq && approxMeters < minDegSq) {
        minDegSq = approxMeters;
        closest = s;
      }
    }
    return closest;
  }

  /// Encontra o supermercado com coordenadas mais próximo ou por correspondência de nome (O(1) cacheado)
  static PreloadedSupermarket? findMatch(String name, {double? userLat, double? userLng}) {
    final clean = name.trim();
    if (clean.isEmpty) return null;
    _ensureIndexes();

    final cleanNorm = _normalize(clean);

    // 1. Busca exata (normalizada) em O(1)
    final exactMatch = _exactByNormName![cleanNorm];
    if (exactMatch != null) return exactMatch;

    if (userLat == null && userLng == null && _simpleMatchCache.containsKey(cleanNorm)) {
      return _simpleMatchCache[cleanNorm];
    }

    // 2. Busca onde contém ou tokens coincidem usando lista pré-normalizada
    final tokens = cleanNorm.split(_tokenSplitRegex).where((t) => t.isNotEmpty).toList();

    final List<PreloadedSupermarket> candidates = [];
    for (final entry in _normalizedEntries!) {
      final sNorm = entry.key;
      if (sNorm.contains(cleanNorm) || cleanNorm.contains(sNorm)) {
        candidates.add(entry.value);
      } else if (tokens.isNotEmpty && tokens.every((t) => sNorm.contains(t))) {
        candidates.add(entry.value);
      }
    }

    if (candidates.isEmpty) {
      if (userLat == null && userLng == null) {
        _simpleMatchCache[cleanNorm] = null;
      }
      return null;
    }

    if (candidates.length == 1) {
      final res = candidates.first;
      if (userLat == null && userLng == null) {
        _simpleMatchCache[cleanNorm] = res;
      }
      return res;
    }

    if (userLat != null && userLng != null) {
      PreloadedSupermarket best = candidates.first;
      double bestDist = (best.latitude - userLat) * (best.latitude - userLat) +
          (best.longitude - userLng) * (best.longitude - userLng);
      for (int i = 1; i < candidates.length; i++) {
        final c = candidates[i];
        final d = (c.latitude - userLat) * (c.latitude - userLat) +
            (c.longitude - userLng) * (c.longitude - userLng);
        if (d < bestDist) {
          bestDist = d;
          best = c;
        }
      }
      return best;
    }

    final first = candidates.first;
    _simpleMatchCache[cleanNorm] = first;
    return first;
  }

